fn cid<'a>(value: &'a JsonValue, key: &str) -> &'a str {
    value[key].as_str().unwrap()
}
fn cid_at(value: &JsonValue, path: &[&str]) -> String {
    path.iter()
        .fold(value, |current, field| &current[*field])
        .as_str()
        .unwrap()
        .to_owned()
}

fn forge_output_ref(cwd: &Path, receipt_cid: &str, replacement: &str) -> String {
    let store = ObjectStore::open(cwd);
    let output_cid = store
        .put_canonical(&encode_value_node(&Value::Text(replacement.to_owned())).unwrap())
        .unwrap();
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(receipt_cid).unwrap()).unwrap()
    else {
        panic!("receipt must be a value map")
    };
    let output = entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text("output".to_owned()))
        .unwrap();
    output.1 = Value::Ref(output_cid);
    store
        .put_canonical(&encode_value_node(&Value::Map(entries)).unwrap())
        .unwrap()
}

